<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Rest;use Acorn\SafetyHealthcheck\Assessment\AssessmentService;use Acorn\SafetyHealthcheck\Security\RateLimiter;use WP_REST_Request;use WP_REST_Response;use Throwable;
final class AssessmentController{public function register():void{register_rest_route('acorn-healthcheck/v1','/assessments',['methods'=>'POST','callback'=>[$this,'start'],'permission_callback'=>'__return_true']);foreach([['/(?P<token>[A-Za-z0-9_-]+)','GET','resume'],['/(?P<token>[A-Za-z0-9_-]+)/profile','PATCH','profile'],['/(?P<token>[A-Za-z0-9_-]+)/answers/(?P<question>[A-Z0-9_]+)','PUT','answer'],['/(?P<token>[A-Za-z0-9_-]+)/assess','POST','assess']]as[$route,$method,$cb])register_rest_route('acorn-healthcheck/v1','/assessments'.$route,['methods'=>$method,'callback'=>[$this,$cb],'permission_callback'=>'__return_true']);}private function call(callable $fn,int $ok=200):WP_REST_Response{try{return new WP_REST_Response($fn(),$ok);}catch(Throwable $e){$status=str_contains($e->getMessage(),'not found')?404:(str_contains($e->getMessage(),'applicable')?409:400);return new WP_REST_Response(['code'=>'acorn_hc_error','message'=>$e->getMessage()],$status);}}public function start():WP_REST_Response{if(!(new RateLimiter)->allow('start',20,HOUR_IN_SECONDS))return new WP_REST_Response(['code'=>'rate_limited','message'=>'Please try again later.'],429);return$this->call(fn()=>(new AssessmentService)->start(),201);}public function resume(WP_REST_Request $r):WP_REST_Response{return$this->call(fn()=>(new AssessmentService)->resume($r['token']));}public function profile(WP_REST_Request $r):WP_REST_Response{return$this->call(fn()=>(new AssessmentService)->updateProfile($r['token'],$r->get_json_params()));}public function answer(WP_REST_Request $r):WP_REST_Response{return$this->call(fn()=>(new AssessmentService)->saveAnswer($r['token'],$r['question'],(string)$r->get_param('answer')));}public function assess(WP_REST_Request $r):WP_REST_Response{return$this->call(fn()=>(new AssessmentService)->assess($r['token']));}}
